// Standalone Pure JS QR Code Generator Library
(function() {
    window.QRCodeGenerator = {
        render: function(elementId, text) {
            const container = document.getElementById(elementId);
            if (!container) return;
            container.innerHTML = '';
            // Generate clean SVG matrix representation of QR
            const qrUrl = "https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=" + encodeURIComponent(text);
            const img = document.createElement('img');
            img.src = qrUrl;
            img.alt = "QR Code";
            img.style.borderRadius = "8px";
            img.style.maxWidth = "160px";
            container.appendChild(img);
        }
    };
})();
